import{_ as t,o as s,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Blocs et modèles personnalisés","description":"","frontmatter":{"title":"Blocs et modèles personnalisés"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/custom-blocks.md","filePath":"fr/projects/blocks-for-ha/custom-blocks.md","lastUpdated":1792851775000}'),o={name:"fr/projects/blocks-for-ha/custom-blocks.md"};function n(l,e,i,u,c,p){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="blocs-et-modeles-personnalises" tabindex="-1">Blocs et modèles personnalisés <a class="header-anchor" href="#blocs-et-modeles-personnalises" aria-label="Permalink to &quot;Blocs et modèles personnalisés&quot;">​</a></h1><p>Le bouton <strong>Block-/Template-Editor</strong> ouvre un éditeur occupant environ <strong>95 % de la largeur et de la hauteur</strong> de l’écran. Il crée plusieurs blocs dans un paquet, avec aperçu Blockly et sorties HA/Jinja. Les définitions sont déclaratives ; aucun générateur JavaScript importé n’est exécuté.</p><h2 id="creer-un-paquet" tabindex="-1">Créer un paquet <a class="header-anchor" href="#creer-un-paquet" aria-label="Permalink to &quot;Créer un paquet&quot;">​</a></h2><ol><li>Renseigner ID, version, nom, auteur, licence et description du paquet.</li><li>Ajouter les blocs puis choisir valeur, condition, action ou déclencheur.</li><li>Déclarer les champs : texte, nombre, case à cocher ou entité, et les entrées de valeurs typées.</li><li>Renseigner le modèle de sortie : expression Jinja pour une valeur/condition, structure YAML native pour une action/déclencheur.</li><li>Vérifier l’aperçu et les diagnostics ; appliquer le paquet.</li></ol><p>Les blocs appliqués apparaissent dans <strong>Personnalisés</strong>, avant la recherche. Les IDs techniques sont placés dans un espace de noms propre au paquet. Les noms de champs, variables et IDs ne sont pas traduits. Les libellés des paquets restent dans la langue de leur auteur.</p><h2 id="copier-telecharger-et-importer" tabindex="-1">Copier, télécharger et importer <a class="header-anchor" href="#copier-telecharger-et-importer" aria-label="Permalink to &quot;Copier, télécharger et importer&quot;">​</a></h2><p><strong>JSON prüfen</strong> vérifie le JSON collé. <strong>ZIP einlesen</strong> lit l’archive du même format. Après vérification, <strong>Übernehmen</strong> installe le paquet localement. JSON et ZIP contiennent la même définition ; ils ne doivent pas contenir du code exécutable arbitraire.</p><p>Les projets de format 3 incluent les définitions des paquets utilisés pour permettre la restauration sur un autre navigateur. Les paquets installés sont également conservés localement. Les collisions de types et imports invalides sont refusés ; le contrôle préalable évite une installation partielle.</p><p>Pour publier, fournir nom, description, auteur, licence, version et image, avec du JSON copiable et des téléchargements JSON/ZIP. Aucune publication automatique depuis l’éditeur. <a href="./catalog/">Catalogue des paquets</a>.</p><h2 id="limites" tabindex="-1">Limites <a class="header-anchor" href="#limites" aria-label="Permalink to &quot;Limites&quot;">​</a></h2><p>Le JSON de définition produit par le <a href="https://docs.blockly.com/guides/create-custom-blocks/blockly-developer-tools/" target="_blank" rel="noreferrer">Blockly Developer Tools</a> décrit la forme d’un bloc, mais ne suffit pas à produire une automatisation HA. Il faut un modèle de sortie et un schéma de paquet vérifiable. Les générateurs Python, PHP, JavaScript, Lua et Dart du Block Factory ne sont pas les générateurs HA/Jinja de ce projet.</p><p>Les menus déroulants personnalisés, champs variable/image, conteneurs d’instructions, mutateurs et entrées dynamiques supplémentaires restent des pistes d’évolution. Les références à des blocs inconnus et les sorties non représentables sont refusées.</p><p>Le <a href="./catalog/sensor-light">paquet capteur et lampe</a> illustre une valeur de capteur, une condition de seuil et une action de luminosité. Tester les résultats et remplacer les entités avant utilisation dans HA.</p>',13)])])}const h=t(o,[["render",n]]);export{m as __pageData,h as default};
